   ("Scope 셋의 뜻", [("li",[("Scope 1: 직접 배출",""),("Scope 2: 사서 쓴 전기·증기·난방·냉각에서 나온 간접 배출",""),("Scope 3: 그 밖의 가치사슬 간접 배출","")])]),
