   ("숫자로 보면", [("table","기아 2025년 온실가스 배출량 (보고서 130쪽)",["구분","2025년(천tCO2e)"],[["Scope 1","398.5"],["Scope 2","697.9"],["Scope 1+2 합계","1,096.4"],["Scope 3","142,060.7"]])]),
